// src/components/Navbar.js
import React from "react";
import { FaMapMarkerAlt, FaPhone, FaSearch, FaUser, FaShoppingBag } from "react-icons/fa";
import "./Navbar.scss";

const Navbar = () => {
  return (
    <nav className="navbar">
      {/* Barra superior */}
      <div className="navbar-top">
        <span>FRETE GRÁTIS*</span>
        <span>DEVOLUÇÃO AUTOMÁTICA</span>
        <span>TROCA GRÁTIS* EM LOJA</span>
        <span>PARCELAMENTO ATÉ <strong>10X SEM JUROS*</strong></span>
        <span>TELEATENDIMENTO: (21) 12503-6897</span>
      </div>

      {/* Navbar principal */}
      <div className="navbar-main">
        {/* Ícones à esquerda */}
        <div className="navbar-left">
          <FaMapMarkerAlt />
          <FaPhone />
        </div>

        {/* Nome da marca e menu centralizados */}
        <div className="navbar-center">
          <div className="navbar-brand">ANIMALE</div> {/* Marca acima do menu */}
          <ul className="navbar-links">
            <li><a href="#">NOVIDADES</a></li>
            <li><a href="#">COLEÇÃO</a></li>
            <li><a href="#">JOIAS</a></li>
            <li><a href="#">SALE</a></li>
            <li><a href="#" className="italic">Inside</a></li>
          </ul>
        </div>

        {/* Ícones à direita */}
        <div className="navbar-right">
          <FaSearch />
          <FaUser />
          <span>Olá, Fernanda</span>
          <FaShoppingBag />
          <span className="cart-count">1</span>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
